<template><div class="erp-module-page"><div class="erp-mode-bar"><el-button :type="mode==='list'?'primary':'default'" plain @click="back">管理岗位资料</el-button><el-button v-permission="'add'" :type="mode==='form'&&kind==='create'?'primary':'default'" plain @click="create">岗位资料添加</el-button></div><el-card v-show="mode==='list'" shadow="never"><template #header><span class="page-title">岗位资料</span></template><div class="search-row erp-filter-row"><el-input v-model="keyword" class="key" clearable placeholder="岗位编码 / 岗位名称 / 备注" @keyup.enter="search"/><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button><i class="divider"/><span>显示未审核</span><el-switch v-model="unpass" :disabled="recycle"/><i class="divider"/><span>回收站</span><el-switch v-model="recycle"/></div><el-alert v-if="error" :title="error" type="error" show-icon/><el-pagination background layout="total, sizes, prev, pager, next, jumper" :total="total" :current-page="page" :page-size="size" :page-sizes="ERP_PAGE_SIZE_OPTIONS" @size-change="changeSize" @current-change="changePage"/><el-table v-erp-list-h-scroll :data="rows" row-key="systemcode" border stripe class="erp-list-table"><el-table-column label="操作" fixed="left" :width="actions"><template #default="{row}"><ErpTableActions><el-button type="info" plain @click="view(row)">查看</el-button><el-button v-if="recycle" v-permission="'edit'" type="primary" plain @click="restore(row)">恢复</el-button><template v-else><el-button v-if="unpass" v-permission="'edit'" type="primary" plain @click="edit(row)">编辑</el-button><el-button v-if="unpass" v-permission="'delete'" type="danger" plain @click="del(row)">删除</el-button><el-button v-if="unpass" v-permission="'audit'" type="success" plain @click="audit(row)">审核</el-button><el-button v-if="!unpass" v-permission="'unaudit'" type="warning" plain @click="unaudit(row)">反审</el-button></template></ErpTableActions></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="passed(row)?'success':'info'">{{passed(row)?'已审核':'未审核'}}</el-tag></template></el-table-column><el-table-column prop="code" label="岗位编码" min-width="130"/><el-table-column prop="name" label="岗位名称" min-width="160"/><el-table-column prop="info" label="备注" min-width="220"/><el-table-column label="操作时间" min-width="160"><template #default="{row}">{{row.edittime||row.addtime||'—'}}</template></el-table-column></el-table><el-pagination background layout="total, sizes, prev, pager, next, jumper" :total="total" :current-page="page" :page-size="size" :page-sizes="ERP_PAGE_SIZE_OPTIONS" @size-change="changeSize" @current-change="changePage"/></el-card><section v-show="mode==='form'" class="form"><div class="head"><b>{{title}}</b><span><el-button v-if="kind==='view'" @click="back">返回列表</el-button><template v-else><el-button @click="clear">重置</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></span></div><el-form ref="formRef" :model="item" :rules="rules" :disabled="kind==='view'" label-width="90px"><div class="form-row"><el-form-item label="岗位编码" prop="code"><el-input v-model="item.code" maxlength="50"/></el-form-item><el-form-item label="岗位名称" prop="name"><el-input v-model="item.name" maxlength="50"/></el-form-item></div><el-form-item label="备注" class="remark"><el-input v-model="item.info" type="textarea" :rows="3" maxlength="50"/></el-form-item></el-form></section></div></template>
<script setup>
import {computed, onMounted, ref, watch} from 'vue'; import axios from 'axios'; import {ElMessage,ElMessageBox} from 'element-plus'; import {ERP_PAGE_SIZE_OPTIONS} from '@/utils/erpPagination'; import {getPermissionModelFromStorage,hasPageAction} from '@/utils/menuPermission'; import {getErpTableActionsColWidthByRows} from '@/utils/erpTableActionsLayout';
const path='hr/files/position', model=getPermissionModelFromStorage(), mode=ref('list'),kind=ref('create'),rows=ref([]),total=ref(0),page=ref(1),size=ref(20),keyword=ref(''),unpass=ref(false),recycle=ref(false),error=ref(''),saving=ref(false),formRef=ref(),blank=()=>({systemcode:'',code:'',name:'',info:''}),item=ref(blank()),rules={code:[{required:true,message:'请输入岗位编码',trigger:'blur'}],name:[{required:true,message:'请输入岗位名称',trigger:'blur'}]},passed=r=>String(r?.pass||'')==='1',title=computed(()=>({create:'岗位资料添加',edit:'岗位资料编辑',view:'岗位资料查看'}[kind.value]));
const actions=computed(()=>getErpTableActionsColWidthByRows(rows.value,r=>{const a=['查看'];if(recycle.value){if(hasPageAction(model,path,'edit'))a.push('恢复')}else if(unpass.value){if(hasPageAction(model,path,'edit'))a.push('编辑');if(hasPageAction(model,path,'delete'))a.push('删除');if(hasPageAction(model,path,'audit'))a.push('审核')}else if(hasPageAction(model,path,'unaudit')&&passed(r))a.push('反审');return a}));
async function load(){error.value='';try{const {data}=await axios.get('/api/hr/positions',{params:{page:page.value,pageSize:size.value,keyword:keyword.value,pass:unpass.value?'0':'1',recycle:recycle.value?'1':'0'}});if(data?.code!==200)throw Error(data?.msg);rows.value=data.data?.list||[];total.value=Number(data.data?.total||0)}catch(e){rows.value=[];total.value=0;error.value=String(e?.response?.data?.msg||e?.message||'加载失败')}} function search(){page.value=1;load()} function reset(){keyword.value='';search()} function changeSize(v){size.value=v;page.value=1;load()} function changePage(v){page.value=v;load()} function back(){mode.value='list';load()} function create(){kind.value='create';item.value=blank();mode.value='form'} function edit(r){if(!passed(r)){kind.value='edit';item.value={...blank(),...r};mode.value='form'}} function view(r){kind.value='view';item.value={...blank(),...r};mode.value='form'} function clear(){if(kind.value==='create')item.value=blank()}
async function save(){try{await formRef.value.validate()}catch{return}saving.value=true;try{const p={systemcode:item.value.systemcode,code:item.value.code.trim(),name:item.value.name.trim(),info:item.value.info.trim()};const {data}=kind.value==='edit'?await axios.put('/api/hr/positions',p):await axios.post('/api/hr/positions',p);if(data?.code!==200)throw Error(data?.msg);ElMessage.success('保存成功');back()}catch(e){ElMessage.error(String(e?.response?.data?.msg||e?.message||'保存失败'))}finally{saving.value=false}} async function act(msg,fn){try{await ElMessageBox.confirm(msg,'确认操作',{type:'warning'})}catch{return}try{await fn();await load()}catch(e){ElMessage.error(String(e?.response?.data?.msg||e?.message||'操作失败'))}} const del=r=>act(`确定删除岗位“${r.name}”吗？`,async()=>{const {data}=await axios.delete(`/api/hr/positions/${encodeURIComponent(r.systemcode)}`);if(data?.code!==200)throw Error(data?.msg)}),restore=r=>act(`确定恢复岗位“${r.name}”吗？`,async()=>{const {data}=await axios.put('/api/hr/positions/restore',{systemcode:r.systemcode});if(data?.code!==200)throw Error(data?.msg)}),audit=r=>act(`确定审核岗位“${r.name}”吗？`,async()=>{const {data}=await axios.put('/api/hr/positions/audit',{systemcode:r.systemcode});if(data?.code!==200)throw Error(data?.msg)}),unaudit=r=>act(`确定反审岗位“${r.name}”吗？`,async()=>{const {data}=await axios.put('/api/hr/positions/unaudit',{systemcode:r.systemcode});if(data?.code!==200)throw Error(data?.msg)});watch(unpass,()=>{if(unpass.value)recycle.value=false;search()});watch(recycle,()=>{if(recycle.value)unpass.value=false;search()});onMounted(load)
</script><style scoped>.erp-module-page{min-height:200px}.erp-mode-bar,.search-row,.form-row,.head{display:flex;align-items:center;gap:10px}.erp-mode-bar{margin-bottom:12px}.search-row{margin:8px 0 12px}.key{width:320px}.divider{width:1px;height:24px;background:var(--el-border-color)}.form{padding:18px 22px;border:1px solid var(--el-border-color-lighter)}.head{justify-content:space-between;border-bottom:1px solid var(--el-border-color-lighter);padding-bottom:16px;margin-bottom:18px}.form-row .el-form-item{width:250px}.remark{width:500px}@media(max-width:720px){.search-row{flex-wrap:wrap}.form-row{display:block}.form-row .el-form-item,.remark,.key{width:100%}}</style>
